B = copy.deepcopy(g.OPTIONS["B"])
for r in B["rooms"]:
    r["area"] = round(g.area(r["polygon"]), 2)
# проверка перекрытий помещений и попадания новых стен в помещения
def overlap(p, q):
    xs = sorted({v[0] for v in p + q}); ys = sorted({v[1] for v in p + q}); s = 0
    for i in range(len(xs)-1):
        for j in range(len(ys)-1):
            c = ((xs[i]+xs[i+1])/2, (ys[j]+ys[j+1])/2)
            def pin(pt, poly):
                x, y = pt; ins = False
                for (x1, y1), (x2, y2) in zip(poly, poly[1:]+poly[:1]):
                    if (y1 > y) != (y2 > y) and x1 + (y-y1)*(x2-x1)/(y2-y1) > x: ins = not ins
                return ins
            if pin(c, p) and pin(c, q): s += (xs[i+1]-xs[i])*(ys[j+1]-ys[j])
    return s
errs = []
for k, o in g.OPTIONS.items():
    rr = o["rooms"]
    for i in range(len(rr)):
        for j in range(i+1, len(rr)):
            ov = overlap(rr[i]["polygon"], rr[j]["polygon"])
            if ov > 1e4: errs.append((k, rr[i]["id"], rr[j]["id"], ov/1e6))
    for nw in o["new_walls"]:
        x, y, w, h = g.wall_rect(nw["a"], nw["b"], nw["thickness"])
        poly = [[x+5, y+5], [x+w-5, y+5], [x+w-5, y+h-5], [x+5, y+h-5]]
        for r in rr:
            ov = overlap(poly, r["polygon"])
            if ov > 1e4: errs.append((k, nw["id"], "в помещении", r["id"], ov/1e6))
print("collisions:", errs or "нет")

